const webhookJson = $('Webhook').first().json;
const body = webhookJson.body || {};
const inputName = normalizeName(body.name || webhookJson.name || '');

function textFromValue(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(textFromValue).filter(Boolean).join('');
  if (value.plain_text) return String(value.plain_text);
  if (value.name) return String(value.name);
  if (value.title) return textFromValue(value.title);
  if (value.rich_text) return textFromValue(value.rich_text);
  if (value.select) return textFromValue(value.select);
  if (value.checkbox != null) return String(value.checkbox);
  if (value.date) return value.date.start || '';
  return '';
}

function compact(value) {
  return String(value || '').replace(/\s+/g, '').trim();
}

function normalizeName(value) {
  return compact(textFromValue(value));
}

function prop(page, names) {
  const wanted = Array.isArray(names) ? names : [names];
  const wantedCompact = wanted.map(compact);
  const json = page.json || page;
  const props = json.properties || {};

  for (const name of wanted) {
    if (json[name] != null) return json[name];
    if (json['property_' + name] != null) return json['property_' + name];
    if (props[name] != null) return props[name];
  }

  for (const [key, value] of Object.entries({ ...json, ...props })) {
    const normalizedKey = compact(key).replace(/^property_/, '');
    if (wantedCompact.includes(normalizedKey)) return value;
  }

  return undefined;
}

function propText(page, names) {
  return textFromValue(prop(page, names)).trim();
}

function propCheckbox(page, names) {
  const value = prop(page, names);
  if (value == null) return false;
  if (typeof value === 'boolean') return value;
  if (value.checkbox != null) return Boolean(value.checkbox);
  return ['true', 'yes', '1', '已投票'].includes(textFromValue(value).trim().toLowerCase());
}

if (!inputName) {
  return [{ json: { success: false, message: '請輸入投票人姓名' } }];
}

const found = $input.all().find((item) => normalizeName(propText(item, ['姓名', '投票人姓名', 'Name', 'name'])) === inputName);

if (!found) {
  const voter = {
    pageId: '',
    name: String(body.name || '').trim(),
    lineUserId: String(body.lineUserId || '').trim(),
    voted: false,
    chairman: '',
    rep: '',
    city: '',
    inList: false,
    needsAssistance: true
  };
  return [{ json: { success: true, inList: false, needsAssistance: true, message: '\u540d\u55ae\u5167\u672a\u627e\u5230\u6b64\u59d3\u540d\uff0c\u8acb\u627e\u670d\u52d9\u4eba\u54e1\u78ba\u8a8d\uff1b\u672c\u6b21\u4ecd\u5177\u6295\u7968\u8cc7\u683c\u3002', voter } }];
}

const voter = {
  pageId: found.json.id || '',
  name: propText(found, ['\u59d3\u540d', '\u6295\u7968\u4eba\u59d3\u540d', 'Name', 'name']) || body.name || '',
  lineUserId: propText(found, ['LINE USER ID', 'LINE User ID', 'LINE ID']),
  voted: propCheckbox(found, ['\u5df2\u6295\u7968', '\u662f\u5426\u5df2\u6295\u7968', '\u6295\u7968\u72c0\u614b']),
  chairman: propText(found, ['\u9810\u8a2d\u4e3b\u59d4', '\u4e3b\u59d4']),
  rep: propText(found, ['\u9810\u8a2d\u5168\u4ee3', '\u5168\u4ee3']),
  city: propText(found, ['\u9810\u8a2d\u5e02\u4ee3', '\u5e02\u4ee3']),
  inList: true,
  needsAssistance: false
};

return [{ json: { success: true, inList: true, needsAssistance: false, voted: voter.voted, pageId: voter.pageId, voter } }];
